// Normalizzazione deterministica della posizione della risposta corretta:
// alcuni blocchi (es. Tecnologia) avevano tutte le risposte corrette in posizione 0.
// Qui le posizioni vengono ridistribuite in modo deterministico, preservando la risposta corretta.
Object.keys(QBANCO).forEach(function (classe) {
  var lista = QBANCO[classe];
  if (!Array.isArray(lista)) return;
  lista.forEach(function (q, i) {
    if (!q || !Array.isArray(q.ops) || typeof q.r !== 'number') return;
    var n = q.ops.length;
    if (n < 2) return;
    var shift = i % n;
    if (shift === 0) return;
    var old = q.ops;
    q.ops = old.map(function (_, j) { return old[(j - shift + n) % n]; });
    q.r = (q.r + shift) % n;
  });
});

